    { id = "dun-morogh-049", ["do"] = "learn_prof", npc = 1703, prof = "tailoring", at = {1455, 43.8, 27.9}, text = "Aprende Sastrería con Uthrar Threx.", tip = "Guarda todo el paño de lino. Haz madejas y prendas de lino hasta 50-75 antes del 10.", status = "unverified" },
    { id = "dun-morogh-050", ["do"] = "accept", quest = 96059, npc = 11065, at = {1455, 60.3, 45.4}, text = "Ve a Ciudad Manitas y coge la de Encantamiento de Thonys Pillarstone.", status = "unverified", reqlevel = 4 },
    { id = "dun-morogh-051", ["do"] = "learn_prof", npc = 11065, prof = "enchanting", at = {1455, 60.3, 45.4}, text = "Aprende Encantamiento con Thonys Pillarstone.", tip = "Desencanta los verdes que no uses. La Varita mágica inferior es tu primera gran mejora.", status = "unverified" },
    { id = "dun-morogh-052", ["do"] = "turnin", quest = 96059, npc = 11065, at = {1455, 60.3, 45.4}, text = "Entrega la de Encantamiento a Thonys.", status = "unverified" },
    { id = "dun-morogh-053", ["do"] = "accept", quest = 95041, npc = 11028, at = {1455, 67.7, 44.2}, text = "Coge la misión de datos de Jemma Quikswitch, también en Ciudad Manitas.", tip = "Los ventisqueros con datos están junto a los gnomos leprosos, al noroeste de Brewnall.", status = "unverified", reqlevel = 7 },
    { id = "dun-morogh-054", ["do"] = "accept", quest = 312, npc = 1266, at = {1426, 34.6, 51.6}, text = "Sal de Forjaz, baja hacia el oeste y coge la misión de Tundra MacGrann.", status = "unverified", reqlevel = 7 },
    { id = "dun-morogh-055", ["do"] = "turnin", quest = 318, npc = 1374, at = {1426, 30.2, 45.7}, text = "Sigue a Brewnall y entrega a Rejold Barleybrew.", status = "unverified" },
    { id = "dun-morogh-056", ["do"] = "accept", quest = 319, npc = 1374, at = {1426, 30.2, 45.7}, text = "Coge el favor de Rejold: osos, jabalíes y leopardos.", status = "unverified", reqlevel = 2 },
    { id = "dun-morogh-057", ["do"] = "accept", quest = 315, npc = 1374, at = {1426, 30.2, 45.7}, text = "Coge también la cerveza perfecta de Rejold.", status = "unverified", reqlevel = 5 },
    { id = "dun-morogh-058", ["do"] = "accept", quest = 98326, npc = 8508, at = {1426, 31.5, 44.6}, text = "Coge la misión de Frosthowl de Gretta Ganter (nueva de Forever).", tip = "Marleth, al lado, ofrece Bitter Rivals: sáltala, pide dos viajes más por poca experiencia.", status = "unverified", reqlevel = 5 },
    { id = "dun-morogh-059", ["do"] = "complete", quest = 412, at = {1426, 26.0, 40.4}, text = "Al noroeste, mata gnomos leprosos hasta tener los engranajes de Razzle.", status = "unverified" },
    { id = "dun-morogh-060", ["do"] = "complete", quest = 95041, at = {1426, 26.2, 41.0}, text = "Registra los ventisqueros de la misma zona hasta tener los datos de Jemma.", status = "unverified" },
    { id = "dun-morogh-061", ["do"] = "complete", quest = 287, at = {1426, 25.4, 50.4}, text = "Baja al sur, al Bastión Peloescarcha, y mata cazacabezas Peloescarcha.", tip = "Usa Miedo si se te juntan dos. Leopardos y osos del camino cuentan para Rejold.", status = "unverified" },
    { id = "dun-morogh-062", ["do"] = "complete", quest = 315, at = {1426, 41.5, 39.1}, text = "Ve al este, al campamento trol de la colina: recoge hierba trémula de las cestas o de los videntes Peloescarcha.", status = "unverified" },
    { id = "dun-morogh-063", ["do"] = "complete", quest = 98326, at = {1426, 39.3, 48.8}, text = "Entra en la Guarida Grizzled y mata a Frosthowl: suelta el saco de pescado.", status = "unverified" },
    { id = "dun-morogh-064", ["do"] = "complete", quest = 312, at = {1426, 38.5, 53.9}, text = "Sal por el sur de la Guarida y abre la despensa de MacGrann.", tip = "Cerca anda Old Icebeard, un oso de más nivel: espera a que se aleje antes de abrirla.", status = "unverified" },
    { id = "dun-morogh-065", ["do"] = "complete", quest = 319, at = {1426, 36.0, 47.0}, text = "Termina los osos, jabalíes y leopardos que te falten para Rejold.", status = "unverified" },
    { id = "dun-morogh-066", ["do"] = "turnin", quest = 312, npc = 1266, at = {1426, 34.6, 51.6}, text = "Entrega la carne a Tundra MacGrann.", status = "unverified" },
    { id = "dun-morogh-067", ["do"] = "turnin", quest = 98326, npc = 8508, at = {1426, 31.5, 44.6}, text = "Vuelve a Brewnall y entrega el pescado a Gretta.", status = "unverified" },
    { id = "dun-morogh-068", ["do"] = "turnin", quest = 315, npc = 1374, at = {1426, 30.2, 45.7}, text = "Entrega la hierba a Rejold.", status = "unverified" },
    { id = "dun-morogh-069", ["do"] = "accept", quest = 413, npc = 1374, at = {1426, 30.2, 45.7}, text = "Coge la cerveza para el montañero Barleybrew, en el extremo este de la zona.", status = "unverified", reqlevel = 8 },
    { id = "dun-morogh-070", ["do"] = "turnin", quest = 319, npc = 1374, at = {1426, 30.2, 45.7}, text = "Entrega el favor a Rejold.", status = "unverified" },
    { id = "dun-morogh-071", ["do"] = "accept", quest = 320, npc = 1374, at = {1426, 30.2, 45.7}, text = "Coge la vuelta con Bellowfiz.", status = "unverified", reqlevel = 2 },
    { id = "dun-morogh-072", ["do"] = "turnin", quest = 287, npc = 1252, at = {1426, 46.7, 53.8}, text = "Vuelve a Kharanos y entrega el Bastión a Senir.", status = "unverified" },
    { id = "dun-morogh-073", ["do"] = "accept", quest = 291, npc = 1252, at = {1426, 46.7, 53.8}, text = "Coge los informes de Senir: se entregan en Forjaz.", status = "unverified" },
    { id = "dun-morogh-074", ["do"] = "turnin", quest = 412, npc = 1269, at = {1426, 45.9, 49.4}, text = "Entrega los engranajes a Razzle.", status = "unverified" },
    { id = "dun-morogh-075", ["do"] = "turnin", quest = 320, npc = 1378, at = {1426, 49.4, 48.4}, text = "Entrega a Bellowfiz.", status = "unverified" },
    { id = "dun-morogh-076", ["do"] = "accept", quest = 96408, npc = 1376, at = {1426, 50.4, 49.1}, text = "Coge de Beldin Steelgrill la visita al vidente de la tierra Farsen (nivel 9).", status = "unverified", reqlevel = 9 },
    { id = "dun-morogh-077", ["do"] = "turnin", quest = 99158, npc = 1253, at = {1426, 57.7, 44.9}, text = "Ve al noreste de Kharanos y entrega la misión de Maxan al padre Gavin.", status = "unverified" },
    { id = "dun-morogh-078", ["do"] = "accept", quest = 99159, npc = 1253, at = {1426, 57.7, 44.9}, text = "Coge la leña del padre Gavin.", status = "unverified", reqlevel = 5 },
    { id = "dun-morogh-079", ["do"] = "complete", quest = 99159, at = {1426, 56.1, 51.9}, text = "Recoge leña seca de los troncos caídos al sur de Gavin.", status = "unverified" },
    { id = "dun-morogh-080", ["do"] = "turnin", quest = 99159, npc = 1253, at = {1426, 57.7, 44.9}, text = "Entrega la leña a Gavin.", status = "unverified" },
    { id = "dun-morogh-081", ["do"] = "accept", quest = 99160, npc = 1253, at = {1426, 57.7, 44.9}, text = "Coge la primera de los elementales de escarcha.", status = "unverified", reqlevel = 5 },
    { id = "dun-morogh-082", ["do"] = "accept", quest = 99162, npc = 1253, at = {1426, 57.7, 44.9}, text = "Coge también la de los rifles de los montañeros caídos.", status = "unverified", reqlevel = 5 },
    { id = "dun-morogh-083", ["do"] = "complete", quest = 99160, at = {1426, 55.3, 45.7}, text = "Mata elementales de hielo menores alrededor de Gavin.", status = "unverified" },
    { id = "dun-morogh-084", ["do"] = "complete", quest = 99162, at = {1426, 52.1, 44.0}, wps = {{1426, 52.1, 44.0, "Rifle 1"}, {1426, 59.9, 50.1, "Rifle 2"}, {1426, 53.2, 58.8, "Rifle 3"}}, text = "Recoge los tres rifles: al oeste, al sureste y al sur de Gavin.", status = "unverified" },
    { id = "dun-morogh-085", ["do"] = "turnin", quest = 99160, npc = 1253, at = {1426, 57.7, 44.9}, text = "Entrega los elementales a Gavin.", status = "unverified" },
    { id = "dun-morogh-086", ["do"] = "turnin", quest = 99162, npc = 1253, at = {1426, 57.7, 44.9}, text = "Entrega los rifles a Gavin.", status = "unverified" },
    { id = "dun-morogh-087", ["do"] = "accept", quest = 99161, npc = 1253, at = {1426, 57.7, 44.9}, text = "Coge la segunda de los elementales: su jefa.", status = "unverified", reqlevel = 5 },
    { id = "dun-morogh-088", ["do"] = "complete", quest = 99161, at = {1426, 58.3, 42.1}, text = "Mata a Avala, al norte de Gavin, y recoge su núcleo.", tip = "Agonía, Corrupción e Inmolar y que el Diablillo dispare; Miedo si te baja de la mitad.", status = "unverified" },
    { id = "dun-morogh-089", ["do"] = "turnin", quest = 99161, npc = 1253, at = {1426, 57.7, 44.9}, text = "Entrega el núcleo a Gavin.", status = "unverified" },
    { id = "dun-morogh-090", ["do"] = "accept", quest = 95212, npc = 1265, at = {1426, 63.1, 49.9}, text = "Sigue al este hasta la granja Amberstill y coge la misión de pieles de Rudra Amberstill.", status = "unverified", reqlevel = 7 },
    { id = "dun-morogh-091", ["do"] = "accept", quest = 314, npc = 1265, at = {1426, 63.1, 49.9}, text = "Coge también la de Vagash de Rudra; la harás al volver, ya con más nivel.", status = "unverified", reqlevel = 6 },
    { id = "dun-morogh-092", ["do"] = "turnin", quest = 96408, npc = 264936, at = {1426, 64.9, 58.5}, text = "Ve al sur y entrega a Earthseer Farsen.", status = "unverified" },
    { id = "dun-morogh-093", ["do"] = "accept", quest = 96392, npc = 264936, at = {1426, 64.9, 58.5}, text = "Coge la vigilancia de Farsen.", status = "unverified", reqlevel = 9 },
    { id = "dun-morogh-094", ["do"] = "complete", quest = 96392, at = {1426, 64.9, 58.5}, text = "Habla con Farsen y pídele su visión para observar a los Hierro Negro.", status = "unverified" },
    { id = "dun-morogh-095", ["do"] = "turnin", quest = 96392, npc = 264936, at = {1426, 64.9, 58.5}, text = "Entrega la vigilancia a Farsen.", status = "unverified" },
    { id = "dun-morogh-096", ["do"] = "accept", quest = 96390, npc = 264936, at = {1426, 64.9, 58.5}, text = "Coge la de los espías Hierro Negro.", tip = "Farsen también ofrece Old Ironforge Incursion: es de la mazmorra Hall of Thanes; cógela solo si vas a ir en grupo.", status = "unverified", reqlevel = 9 },
    { id = "dun-morogh-097", ["do"] = "accept", quest = 432, npc = 1254, at = {1426, 69.1, 56.3}, text = "Ve a la cantera de Gol'Bolar y coge la de los troggs del capataz Stonebrow.", status = "unverified", reqlevel = 5 },
    { id = "dun-morogh-098", ["do"] = "accept", quest = 433, npc = 1977, at = {1426, 68.7, 56.0}, text = "Coge la del senador Mehr Stonehallow, al lado.", tip = "Frast Dokner pide barras de cobre: sáltala si no tienes Minería.", status = "unverified", reqlevel = 6 },
    { id = "dun-morogh-099", ["do"] = "accept", quest = 95213, item = 268548, at = {1426, 70.3, 55.9}, text = "Mata troggs de la cantera hasta que caiga el barril de pólvora vacío y úsalo para empezar la misión.", status = "unverified", reqlevel = 7 },
    { id = "dun-morogh-100", ["do"] = "turnin", quest = 95213, npc = 1256, at = {1426, 69.2, 54.8}, text = "Entrega el barril al maestro de cantera Thesten.", status = "unverified" },
    { id = "dun-morogh-101", ["do"] = "accept", quest = 95214, npc = 1256, at = {1426, 69.2, 54.8}, text = "Coge la pólvora robada de Thesten.", status = "unverified", reqlevel = 7 },
    { id = "dun-morogh-102", ["do"] = "complete", quest = 432, at = {1426, 70.3, 55.9}, text = "Dentro de la cantera, mata troggs aplastacráneos.", tip = "Abisario aún no: los troggs pegan fuerte en grupo. Miedo al segundo y DoTs al primero.", status = "unverified" },
    { id = "dun-morogh-103", ["do"] = "complete", quest = 433, at = {1426, 73.5, 54.5}, text = "Más al fondo, mata troggs rompehuesos.", status = "unverified" },
    { id = "dun-morogh-104", ["do"] = "complete", quest = 95214, at = {1426, 73.6, 55.1}, text = "Mata emboscadores trogg hasta recuperar la pólvora.", status = "unverified" },
    { id = "dun-morogh-105", ["do"] = "turnin", quest = 432, npc = 1254, at = {1426, 69.1, 56.3}, text = "Entrega los troggs a Stonebrow.", status = "unverified" },
    { id = "dun-morogh-106", ["do"] = "turnin", quest = 433, npc = 1977, at = {1426, 68.7, 56.0}, text = "Entrega al senador Mehr.", status = "unverified" },
    { id = "dun-morogh-107", ["do"] = "turnin", quest = 95214, npc = 1256, at = {1426, 69.2, 54.8}, text = "Entrega la pólvora a Thesten.", status = "unverified" },
    { id = "dun-morogh-108", ["do"] = "complete", quest = 95212, at = {1426, 75.8, 56.4}, text = "Al este de la cantera, mata leopardos de las nieves ancianos hasta tener las pieles impecables.", status = "unverified" },
    { id = "dun-morogh-109", ["do"] = "complete", quest = 96390, at = {1426, 77.5, 61.2}, text = "Al sureste, mata espías Hierro Negro.", status = "unverified" },
    { id = "dun-morogh-110", ["do"] = "accept", quest = 419, npc = 1960, at = {1426, 83.9, 39.2}, text = "Sube al noreste y coge la misión del piloto Hammerfoot.", status = "unverified", reqlevel = 8 },
    { id = "dun-morogh-111", ["do"] = "turnin", quest = 419, at = {1426, 79.7, 36.2}, text = "Busca al oeste el cadáver del enano y entrega la misión en él.", status = "unverified" },
    { id = "dun-morogh-112", ["do"] = "accept", quest = 417, at = {1426, 79.7, 36.2}, text = "Coge del mismo cadáver la venganza del piloto.", status = "unverified", reqlevel = 8 },
    { id = "dun-morogh-113", ["do"] = "complete", quest = 417, at = {1426, 78.3, 37.8}, text = "Mata a Mangeclaw, el oso que ronda el cadáver, y recoge su garra.", tip = "Es más duro que un oso normal: DoTs, Diablillo y Miedo cuando te baje de la mitad.", status = "unverified" },
    { id = "dun-morogh-114", ["do"] = "turnin", quest = 417, npc = 1960, at = {1426, 83.9, 39.2}, text = "Entrega la garra al piloto Hammerfoot.", status = "unverified" },
    { id = "dun-morogh-115", ["do"] = "turnin", quest = 413, npc = 1959, at = {1426, 86.3, 48.8}, text = "Baja al túnel de Loch Modan y entrega la cerveza al montañero Barleybrew.", status = "unverified" },
    { id = "dun-morogh-116", ["do"] = "accept", quest = 414, npc = 1959, at = {1426, 86.3, 48.8}, text = "Coge la cerveza para Kadrell: la entregarás en Thelsamar (Loch Modan).", status = "unverified", reqlevel = 8 },
    { id = "dun-morogh-117", ["do"] = "turnin", quest = 96390, npc = 264936, at = {1426, 64.9, 58.5}, text = "Vuelve al oeste y entrega los espías a Farsen.", status = "unverified" },
    { id = "dun-morogh-118", ["do"] = "complete", quest = 314, at = {1426, 62.6, 46.0}, optional = true, text = "Busca a Vagash al norte de la granja Amberstill y mátalo para conseguir su colmillo.", tip = "Es de nivel alto para ti. Si no lo matas con DoTs, Diablillo y Miedo, sáltala.", status = "unverified" },
    { id = "dun-morogh-119", ["do"] = "turnin", quest = 314, npc = 1265, at = {1426, 63.1, 49.9}, optional = true, text = "Entrega el colmillo a Rudra Amberstill.", status = "unverified" },
    { id = "dun-morogh-120", ["do"] = "turnin", quest = 95212, npc = 1265, at = {1426, 63.1, 49.9}, text = "Entrega las pieles a Rudra.", status = "unverified" },
    { id = "dun-morogh-121", ["do"] = "turnin", quest = 291, npc = 1274, at = {1455, 39.5, 57.5}, text = "Ve a Forjaz y entrega los informes al senador Barin Redstone, en el Alto Trono.", status = "unverified" },
    { id = "dun-morogh-122", ["do"] = "turnin", quest = 95041, npc = 11028, at = {1455, 67.7, 44.2}, text = "Entrega los datos a Jemma Quikswitch en Ciudad Manitas.", status = "unverified" },
    { id = "dun-morogh-123", ["do"] = "train", npc = 5172, spells = {1120, 6201, 696, 707}, at = {1455, 50.4, 5.7}, text = "Ve a la Caverna Abandonada y entrena con Briarthorn: Drenar alma, Crear piedra de salud y los rangos nuevos.", tip = "Si ya eres 12, entrena también Cauce de salud. Guarda 2-3 Fragmentos de alma y haz una Piedra de salud.", status = "unverified" },
    { id = "dun-morogh-124", ["do"] = "skill", prof = "tailoring", skill = 50, at = {1455, 43.8, 27.9}, optional = true, text = "Sube Sastrería con el paño que tengas (madejas de lino y prendas sencillas).", tip = "Con 50 entrena Oficial. Aprende con Thonys la Varita mágica inferior en cuanto llegues al rango.", status = "unverified" },
  },
})

Senda.Guides:RegisterSection({
  id = "wl-voidwalker",
  title = "Brujo: el Abisario",
  levels = {10, 12},
  map = 1453,
  summary = "Cadena de clase del nivel 10: Gakin en El Cordero Degollado (Ventormenta), la gargantilla de Surena Caledon en Elwynn y la vinculación en el círculo del sótano.",
  ["if"] = { class = {"WARLOCK"} },
  steps = {
    { id = "wl-voidwalker-001", ["do"] = "accept", quest = 1715, npc = 6120, at = {1455, 47.6, 9.3}, ["if"] = { race = {"Gnome"} }, text = "En la Caverna Abandonada de Forjaz, coge la misión de Lago Blackwrench.", status = "unverified", reqlevel = 10 },
    { id = "wl-voidwalker-002", ["do"] = "accept", quest = 1685, npc = 6121, at = {1429, 44.5, 66.3}, ["if"] = { race = {"Human"} }, text = "En la posada de Villadorada, coge la misión de Remen Marcot.", status = "unverified", reqlevel = 10 },
    { id = "wl-voidwalker-003", ["do"] = "goto", at = {1455, 76.0, 51.0}, radius = 15, ["if"] = { race = {"Gnome", "Dwarf"} }, text = "Ve a Ciudad Manitas y coge el Tranvía Subterráneo hasta Ventormenta.", tip = "No hace falta pasar por Villadorada: eso es solo para humanos.", status = "unverified" },
    { id = "wl-voidwalker-004", ["do"] = "getfp", npc = 352, at = {1453, 71.3, 72.2}, node = "2", text = "Coge la ruta de vuelo de Ventormenta con Dungar Longdrink.", tip = "Así vuelves a Forjaz en grifo al acabar.", status = "unverified" },
    { id = "wl-voidwalker-005", ["do"] = "turnin", quest = 1715, npc = 6122, at = {1453, 39.2, 85.2}, ["if"] = { race = {"Gnome"} }, text = "Ve a El Cordero Degollado, en el Barrio de los Magos, baja al sótano y entrega a Gakin el Vinculador.", tip = "Si la flecha no cuadra con el sótano, la guía antigua lo situaba en 25.3, 78.2 (mapa clásico).", status = "unverified" },
    { id = "wl-voidwalker-006", ["do"] = "turnin", quest = 1685, npc = 6122, at = {1453, 39.2, 85.2}, ["if"] = { race = {"Human"} }, text = "Ve a El Cordero Degollado, baja al sótano y entrega a Gakin el Vinculador.", status = "unverified" },
    { id = "wl-voidwalker-007", ["do"] = "accept", quest = 1688, npc = 6122, at = {1453, 39.2, 85.2}, text = "Coge la misión de Surena Caledon de Gakin.", status = "unverified", reqlevel = 10 },
    { id = "wl-voidwalker-008", ["do"] = "train", npc = 461, spells = {755}, at = {1453, 39.2, 85.0}, ["if"] = { minlevel = 12 }, optional = true, text = "Si eres 12, entrena Cauce de salud con Demisette Cloyce, en la misma sala.", status = "unverified" },
    { id = "wl-voidwalker-009", ["do"] = "complete", quest = 1688, at = {1429, 71.0, 80.8}, text = "Sal por la puerta de Ventormenta, cruza Elwynn hasta la Plantación de Calabazas de Brackwell y mata a Surena Caledon.", tip = "Es nivel 9 con dos guardias: sepáralos o pon Miedo a uno. Llévate su gargantilla (en grupo, cada uno recibe la suya).", status = "unverified" },
    { id = "wl-voidwalker-010", ["do"] = "turnin", quest = 1688, npc = 6122, at = {1453, 39.2, 85.2}, text = "Vuelve a Ventormenta y entrega la gargantilla a Gakin.", status = "unverified" },
    { id = "wl-voidwalker-011", ["do"] = "accept", quest = 1689, npc = 6122, at = {1453, 39.2, 85.2}, text = "Coge La vinculación de Gakin.", status = "unverified", reqlevel = 10 },
    { id = "wl-voidwalker-012", ["do"] = "complete", quest = 1689, at = {1453, 39.1, 84.4}, text = "Con vida y maná llenos, usa la gargantilla en el círculo de invocación, bajo la sala de Gakin, y derrota al Abisario.", tip = "DoTs, Diablillo al ataque, Miedo cuando llegue a ti y remata. Ten una Piedra de salud a mano.", status = "unverified" },
    { id = "wl-voidwalker-013", ["do"] = "turnin", quest = 1689, npc = 6122, at = {1453, 39.2, 85.2}, text = "Entrega La vinculación a Gakin.", status = "unverified" },
    { id = "wl-voidwalker-014", ["do"] = "train", spells = {697}, at = {1453, 39.2, 85.2}, text = "Invoca al Abisario y ponlo en pasivo: lo mandas tú.", tip = "Tormento para recuperar la amenaza, Consumir sombras fuera de combate y Sacrificio si vas a morir.", status = "unverified" },
    { id = "wl-voidwalker-015", ["do"] = "fly", npc = 352, at = {1453, 71.3, 72.2}, zone = 1455, ["if"] = { race = {"Gnome", "Dwarf"} }, text = "Vuela de vuelta a Forjaz y sigue hacia Loch Modan.", status = "unverified" },
  },
})

Senda.Guides:RegisterSection({
  id = "wl-succubus",
  title = "Brujo: Súcubo o Íncubo",
  levels = {20, 24},
  map = 1453,
  summary = "Gakin te manda con Takar el Vidente en Los Baldíos. Eliges Súcubo (corazón de madera) o Íncubo (figurilla de madera), ambos en Vallefresno, y haces la vinculación en Ventormenta.",
  ["if"] = { class = {"WARLOCK"} },
  steps = {
    { id = "wl-succubus-001", ["do"] = "accept", quest = 1717, npc = 6120, at = {1455, 47.6, 9.3}, ["if"] = { race = {"Gnome"} }, optional = true, text = "Si pasas por Forjaz, coge el aviso de Lago Blackwrench en la Caverna Abandonada.", tip = "Es solo un recado: si estás ya en Ventormenta, ve directo a Gakin.", status = "unverified", reqlevel = 20 },
    { id = "wl-succubus-002", ["do"] = "turnin", quest = 1717, npc = 6122, at = {1453, 39.2, 85.2}, ["if"] = { race = {"Gnome"} }, optional = true, text = "Entrega el aviso a Gakin, en el sótano de El Cordero Degollado.", status = "unverified" },
    { id = "wl-succubus-003", ["do"] = "accept", quest = 1716, npc = 6122, at = {1453, 39.2, 85.2}, text = "Coge de Gakin la misión que te manda con Takar el Vidente, en Los Baldíos.", status = "unverified", reqlevel = 20 },
    { id = "wl-succubus-004", ["do"] = "train", npc = 461, spells = {1490, 706, 698, 5740}, at = {1453, 39.2, 85.0}, text = "Entrena con Demisette Cloyce, en la misma sala: Maldición de los elementos, Armadura demoníaca, Ritual de invocación y Lluvia de fuego.", status = "unverified" },
    { id = "wl-succubus-005", ["do"] = "note", npc = 11867, at = {1453, 63.9, 69.1}, optional = true, text = "Aprende Bastones con Woo Ping, el maestro de armas del Distrito de Comercio.", tip = "En Forjaz no se enseñan. Sin ellos no podrás llevar el Bastón de Soran'ruk.", status = "unverified" },
    { id = "wl-succubus-006", ["do"] = "turnin", quest = 1716, npc = 6244, at = {1413, 49.3, 57.1}, text = "Viaja a Los Baldíos y entrega a Takar el Vidente.", tip = "Ruta típica: barco de Menethil a Theramore y a pie hacia el oeste. Es zona de la Horda: cuidado con los guardias.", status = "unverified" },
    { id = "wl-succubus-007", ["do"] = "accept", quest = 1738, npc = 6244, at = {1413, 49.3, 57.1}, optional = true, text = "Súcubo: coge de Takar la misión del corazón de madera.", tip = "Elige uno: Súcubo o Íncubo. Los grimorios no se pasan de uno a otro. La cadena del Súcubo es algo más sencilla.", status = "unverified", reqlevel = 20 },
    { id = "wl-succubus-008", ["do"] = "accept", quest = 65602, npc = 6244, at = {1413, 49.3, 57.1}, optional = true, text = "Íncubo: coge de Takar la misión de la figurilla de madera.", status = "unverified", reqlevel = 20 },
    { id = "wl-succubus-009", ["do"] = "accept", quest = 1740, npc = 6247, at = {1413, 49.3, 57.2}, optional = true, text = "Coge también la del Orbe de Soran'ruk de Doan Karhan, junto a Takar.", tip = "3 fragmentos de los acólitos Crepusculares (Cavernas de Brazanegra) y 1 grande en el Castillo de Colmillo Oscuro. Recompensa: bastón u orbe.", status = "unverified", reqlevel = 20 },
    { id = "wl-succubus-010", ["do"] = "complete", quest = 1738, at = {1440, 31.6, 31.6}, optional = true, text = "Súcubo: en Vallefresno, ve a las ruinas de Ordil'Aran y coge el corazón de madera del árbol.", status = "unverified" },
    { id = "wl-succubus-011", ["do"] = "complete", quest = 65602, at = {1440, 26.6, 22.0}, optional = true, text = "Íncubo: en Vallefresno, sube al piso de arriba de la casa al norte del Puesto de Maestra y coge la figurilla de madera.", tip = "Enciende la antorcha apagada y quema el carro para distraer a los arqueólogos.", status = "unverified" },
    { id = "wl-succubus-012", ["do"] = "turnin", quest = 1738, npc = 6122, at = {1453, 39.2, 85.2}, optional = true, text = "Súcubo: vuelve a Ventormenta y entrega el corazón a Gakin.", status = "unverified" },
    { id = "wl-succubus-013", ["do"] = "turnin", quest = 65602, npc = 6122, at = {1453, 39.2, 85.2}, optional = true, text = "Íncubo: vuelve a Ventormenta y entrega la figurilla a Gakin.", status = "unverified" },
    { id = "wl-succubus-014", ["do"] = "accept", quest = 1739, npc = 6122, at = {1453, 39.2, 85.2}, optional = true, text = "Súcubo: coge La vinculación de Gakin.", status = "unverified", reqlevel = 20 },
    { id = "wl-succubus-015", ["do"] = "accept", quest = 65603, npc = 6122, at = {1453, 39.2, 85.2}, optional = true, text = "Íncubo: coge La vinculación de Gakin.", status = "unverified", reqlevel = 20 },
    { id = "wl-succubus-016", ["do"] = "complete", quest = 1739, at = {1453, 39.1, 84.4}, optional = true, text = "Súcubo: usa el objeto en el círculo del sótano y derrota a la súcubo invocada.", tip = "Vida y maná llenos. Abisario a tanquear, DoTs y Drenar vida. Miedo si se suelta.", status = "unverified" },
    { id = "wl-succubus-017", ["do"] = "complete", quest = 65603, at = {1453, 39.1, 84.4}, optional = true, text = "Íncubo: usa el objeto en el círculo del sótano y derrota al íncubo invocado.", tip = "Vida y maná llenos. Abisario a tanquear, DoTs y Drenar vida. Miedo si se suelta.", status = "unverified" },
    { id = "wl-succubus-018", ["do"] = "turnin", quest = 1739, npc = 6122, at = {1453, 39.2, 85.2}, optional = true, text = "Súcubo: entrega La vinculación a Gakin y aprende a invocarla.", status = "unverified" },
    { id = "wl-succubus-019", ["do"] = "turnin", quest = 65603, npc = 6122, at = {1453, 39.2, 85.2}, optional = true, text = "Íncubo: entrega La vinculación a Gakin y aprende a invocarlo.", status = "unverified" },
    { id = "wl-succubus-020", ["do"] = "note", text = "Súcubo o Íncubo para subir (más daño). El Abisario sigue siendo mejor contra dos enemigos o contra élites.", status = "unverified" },
  },
})

Senda.Guides:RegisterSection({
  id = "wl-felhunter",
  title = "Brujo: el Manáfago",
  levels = {30, 34},
  map = 1413,
  summary = "Strahad Farsan (Trinquete) te manda con Krom Stoutarm (Forjaz). Juntas el tomo mohoso (Trabalomas), el manuscrito (Mil Agujas) y 3 varas de canalización (Los Humedales) y haces la vinculación en la torre de Strahad.",
  ["if"] = { class = {"WARLOCK"} },
  steps = {
    { id = "wl-felhunter-001", ["do"] = "accept", quest = 1798, npc = 6120, at = {1455, 47.6, 9.3}, text = "Coge de Lago Blackwrench, en la Caverna Abandonada de Forjaz, la misión que te manda con Strahad.", tip = "Gakin, en Ventormenta, da la misma misión. Entrena el 30 a la vez con Briarthorn: Subyugar demonio y Piroinferno.", status = "unverified", reqlevel = 30 },
    { id = "wl-felhunter-002", ["do"] = "train", npc = 5172, spells = {1098, 1949}, at = {1455, 50.4, 5.7}, text = "Entrena el 30 con Briarthorn: Subyugar demonio y Piroinferno.", status = "unverified" },
    { id = "wl-felhunter-003", ["do"] = "turnin", quest = 1798, npc = 6251, at = {1413, 62.6, 35.5}, text = "Ve a Trinquete (Los Baldíos) y entrega a Strahad Farsan, en su torre.", tip = "Barco de Bahía del Botín a Trinquete, o de Menethil a Theramore y a pie.", status = "unverified" },
    { id = "wl-felhunter-004", ["do"] = "accept", quest = 1758, npc = 6251, at = {1413, 62.6, 35.5}, text = "Coge la primera parte del Tomo de la Cábala de Strahad.", status = "unverified", reqlevel = 30 },
    { id = "wl-felhunter-005", ["do"] = "turnin", quest = 1758, npc = 6294, at = {1455, 74.2, 9.4}, text = "Vuelve a Forjaz y entrega a Krom Stoutarm, en la Sala de los Exploradores.", status = "unverified" },
    { id = "wl-felhunter-006", ["do"] = "accept", quest = 1802, npc = 6294, at = {1455, 74.2, 9.4}, text = "Coge de Krom la misión de las dos páginas del tomo.", status = "unverified", reqlevel = 30 },
    { id = "wl-felhunter-007", ["do"] = "complete", quest = 1802, obj = 1, at = {1424, 27.8, 72.8}, text = "Coge el tomo mohoso en el campamento múrloc de la costa de Laderas de Trabalomas.", status = "unverified" },
    { id = "wl-felhunter-008", ["do"] = "complete", quest = 1802, obj = 2, at = {1441, 43.4, 32.7}, text = "Coge el manuscrito del cofre dañado del Campamento Pezuña Quebrada, en Las Mil Agujas.", tip = "Los centauros van en grupos: Miedo a uno y Abisario o Súcubo con el otro.", status = "unverified" },
    { id = "wl-felhunter-009", ["do"] = "turnin", quest = 1802, npc = 6294, at = {1455, 74.2, 9.4}, text = "Entrega las dos páginas a Krom en Forjaz.", status = "unverified" },
    { id = "wl-felhunter-010", ["do"] = "accept", quest = 1804, npc = 6294, at = {1455, 74.2, 9.4}, text = "Coge la última parte del tomo de Krom.", status = "unverified", reqlevel = 30 },
    { id = "wl-felhunter-011", ["do"] = "complete", quest = 1804, at = {1437, 48.6, 47.1}, wps = {{1437, 51.0, 45.0, "Entrada trasera"}, {1437, 52.6, 52.9, "Guardasombras"}}, text = "En Los Humedales, mata lanzadores Faucedraco del Campamento Dentellada hasta tener 3 varas de canalización.", tip = "Entra por detrás (hacia 51, 45) para tirar de uno en uno.", status = "unverified" },
    { id = "wl-felhunter-012", ["do"] = "turnin", quest = 1804, npc = 6251, at = {1413, 62.6, 35.5}, text = "Lleva el tomo y las varas a Strahad, en Trinquete.", status = "unverified" },
    { id = "wl-felhunter-013", ["do"] = "accept", quest = 1795, npc = 6251, at = {1413, 62.6, 35.5}, text = "Coge La vinculación de Strahad.", status = "unverified", reqlevel = 30 },
    { id = "wl-felhunter-014", ["do"] = "complete", quest = 1795, at = {1413, 62.6, 35.3}, text = "Usa el tomo en el círculo de la torre de Strahad y derrota al manáfago invocado.", tip = "Vida y maná llenos. Demonio a tanquear, DoTs y Drenar vida.", status = "unverified" },
    { id = "wl-felhunter-015", ["do"] = "turnin", quest = 1795, npc = 6251, at = {1413, 62.6, 35.5}, text = "Entrega La vinculación a Strahad.", status = "unverified" },
    { id = "wl-felhunter-016", ["do"] = "train", spells = {691}, at = {1413, 62.6, 35.5}, text = "Ya puedes invocar al Manáfago.", tip = "Para subir sigue con el Súcubo o el Íncubo. El Manáfago es para enemigos lanzadores (Bloqueo de hechizo) y JcJ. Desde aquí, Drenar vida es tu relleno.", status = "unverified" },
  },
})

