    { id = "wl-inferno-004", ["do"] = "complete", quest = 7602, obj = 2, at = {1448, 37.6, 50.2}, text = "Mata legionarios de Jaedenar, al sur de Niby, hasta que caiga su esencia.", status = "unverified" },
