    { id = "wl-inferno-006", ["do"] = "complete", quest = 7602, obj = 3, at = {1419, 58.5, 51.2}, text = "En Las Tierras Devastadas, mata guardias viles centinela junto al Portal Oscuro hasta que caiga su esencia.", status = "unverified" },
    { id = "wl-inferno-007", ["do"] = "turnin", quest = 7602, npc = 14470, at = {1448, 41.4, 45.0}, text = "Vuelve a Frondavil y entrega las esencias a Impsy.", status = "unverified" },
    { id = "wl-inferno-008", ["do"] = "accept", quest = 7603, npc = 14470, at = {1448, 41.4, 45.0}, text = "Coge de Impsy la misión de Kroshius.", status = "unverified", reqlevel = 50 },
